import os
import json
from collections import Counter


def task_func(json_files_path='./json_files/', key='name'):
    """
    Count occurrences of values for `key` across all JSON files in a directory.

    Args:
        json_files_path (str): Path to a directory containing JSON files.
        key (str): The JSON key whose values should be counted.

    Returns:
        dict: A dictionary mapping each encountered value of `key` to its count.
    """

    def _normalize_value(value):
        try:
            hash(value)
            return value
        except TypeError:
            try:
                return json.dumps(value, sort_keys=True, ensure_ascii=False, default=str)
            except TypeError:
                return str(value)

    def _collect(obj, counter):
        if isinstance(obj, dict):
            if key in obj:
                counter[_normalize_value(obj[key])] += 1
            for value in obj.values():
                _collect(value, counter)
        elif isinstance(obj, list):
            for item in obj:
                _collect(item, counter)

    if not os.path.isdir(json_files_path):
        return {}

    counter = Counter()

    for entry in sorted(os.scandir(json_files_path), key=lambda e: e.name):
        if not entry.is_file() or not entry.name.lower().endswith('.json'):
            continue

        try:
            with open(entry.path, 'r', encoding='utf-8') as f:
                data = json.load(f)
        except (OSError, json.JSONDecodeError):
            continue

        _collect(data, counter)

    return dict(counter)
